<script setup lang="ts">
import { ChevronDown, Filter, Plus, Search } from 'lucide-vue-next'
import LocationCreateDrawer from '~/components/LocationCreateDrawer.vue'
import LocationEditDrawer from '~/components/locations/LocationEditDrawer.vue'
import OrganizationTabs from '~/components/organization/OrganizationTabs.vue'
import LocationDataTable from '~/components/locations/LocationDataTable.vue'
import ConfirmationModal from '~/components/ConfirmationModal.vue'
import { locationApi, type LocationApiItem } from '~/api/location'

definePageMeta({ layout: 'default' })
type Location={id:number;name:string;city:string;district:string;address:string;businessEntities:any[];contractorCount:number;status:'active'|'passive';image:string}
const route=useRoute();const tenantId=computed(()=>String(route.params.tenantId??''));const search=ref('');const companyFilter=ref('all');const cityFilter=ref('all');const statusFilter=ref('all');const currentPage=ref(1);const perPage=ref(10);const createDrawerOpen=ref(false);const editDrawerOpen=ref(false);const editingLocation=ref<LocationApiItem|null>(null);const editLoading=ref(false);const deleteDialogOpen=ref(false);const deletingId=ref<number|null>(null);const deleting=ref(false);const locations=ref<Location[]>([]);const loading=ref(true);const error=ref('')
const fallback='https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=500&q=80'
const normalize=(x:LocationApiItem):Location=>{const entities=x.business_entities||x.businessEntities||[];return{id:x.id,name:x.name,city:x.city?.name||'',district:x.district?.name||'',address:x.address||'',businessEntities:entities.filter((e:any)=>e.company).map((e:any)=>({id:e.id,companyName:e.company.name,brandName:(e.company.brands||[]).map((b:any)=>b.name).join(', '),logoUrl:''})),contractorCount:0,status:x.is_active===false?'passive':'active',image:x.image||fallback}}
const load=async()=>{loading.value=true;error.value='';try{const r:any=await locationApi.list(tenantId.value);locations.value=(Array.isArray(r)?r:r?.data||[]).map(normalize)}catch(e){error.value=e instanceof Error?e.message:'Lokasyonlar yüklenemedi.'}finally{loading.value=false}}
onMounted(load)
const companyOptions=computed(()=>[...new Set(locations.value.flatMap(x=>x.businessEntities.map(e=>e.companyName)).filter(Boolean))]);const cityOptions=computed(()=>[...new Set(locations.value.map(x=>x.city).filter(Boolean))])
const filteredLocations=computed(()=>{const t=search.value.trim().toLocaleLowerCase('tr-TR');return locations.value.filter(x=>{const h=`${x.name} ${x.city} ${x.district} ${x.address} ${x.businessEntities.map(e=>`${e.companyName} ${e.brandName||''}`).join(' ')}`.toLocaleLowerCase('tr-TR');return(!t||h.includes(t))&&(companyFilter.value==='all'||x.businessEntities.some(e=>e.companyName===companyFilter.value))&&(cityFilter.value==='all'||x.city===cityFilter.value)&&(statusFilter.value==='all'||x.status===statusFilter.value)})})
const totalPages=computed(()=>Math.max(1,Math.ceil(filteredLocations.value.length/perPage.value)));const paginatedLocations=computed(()=>filteredLocations.value.slice((currentPage.value-1)*perPage.value,currentPage.value*perPage.value));const visiblePages=computed(()=>Array.from({length:Math.min(5,totalPages.value)},(_,i)=>Math.min(Math.max(1,currentPage.value-2)+i,totalPages.value)).filter((p,i,a)=>a.indexOf(p)===i));watch([search,companyFilter,cityFilter,statusFilter,perPage],()=>currentPage.value=1)
const resetFilters=()=>{search.value='';companyFilter.value='all';cityFilter.value='all';statusFilter.value='all'};const goToLocation=(id:number)=>navigateTo(`/tenants/${tenantId.value}/locations/${id}`)
const askDelete=(id:number)=>{deletingId.value=id;deleteDialogOpen.value=true}
const confirmDelete=async()=>{if(deletingId.value===null)return;deleting.value=true;try{await locationApi.remove(tenantId.value,deletingId.value);locations.value=locations.value.filter(l=>l.id!==deletingId.value)}catch(e){error.value=e instanceof Error?e.message:'Lokasyon silinemedi.'}finally{deleting.value=false;deleteDialogOpen.value=false;deletingId.value=null}}
const edit=async(id:number)=>{error.value='';editingLocation.value=null;editDrawerOpen.value=true;editLoading.value=true;try{editingLocation.value=await locationApi.get(tenantId.value,id)}catch(e){error.value=e instanceof Error?e.message:'Lokasyon bilgileri alınamadı.';editDrawerOpen.value=false}finally{editLoading.value=false}}
const upsertLocation=(item:LocationApiItem)=>{const normalized=normalize(item);const idx=locations.value.findIndex(l=>l.id===normalized.id);if(idx!==-1)locations.value.splice(idx,1,normalized);else locations.value=[normalized,...locations.value]}
const update=async(payload:any)=>{if(!editingLocation.value)return;try{const form=new FormData();form.append('name',payload.name);if(payload.city_id!==null)form.append('city_id',String(payload.city_id));if(payload.district_id!==null)form.append('district_id',String(payload.district_id));form.append('address',payload.address);form.append('is_active',payload.status==='active'?'1':'0');if(payload.file instanceof File)form.append('image',payload.file);const updated=await locationApi.update(tenantId.value,editingLocation.value.id,form);upsertLocation(updated);editDrawerOpen.value=false;editingLocation.value=null}catch(e){error.value=e instanceof Error?e.message:'Lokasyon güncellenemedi.'}}
</script>
<template><div class="font-outfit"><div class="mx-auto w-full max-w-[1400px]"><div class="mb-6"><h1 class="text-2xl font-semibold tracking-tight text-gray-900 dark:text-white/90">Lokasyonlar</h1><p class="mt-1.5 text-sm text-gray-500 dark:text-gray-400">Tenant içerisindeki fiziksel lokasyonları görüntüleyin ve yönetin.</p></div><OrganizationTabs :tabs="[{label:'Lokasyonlar',to:`/tenants/${tenantId}/locations`,exact:true},{label:'Lokasyon Organizasyon Eşleştirmesi',to:`/tenants/${tenantId}/locations/organization`}]"/><div class="mb-5 flex justify-end"><button type="button" class="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-500 px-4 text-sm font-semibold text-white" @click="createDrawerOpen=true"><Plus :size="16"/> Yeni Lokasyon</button></div><div v-if="error" class="mb-4 rounded-lg border border-error-200 bg-error-50 px-4 py-3 text-sm text-error-600">{{error}}</div><section class="mb-5 rounded-xl border border-gray-200 bg-white p-4 shadow-theme-xs dark:border-gray-800 dark:bg-white/[0.03]"><div class="grid grid-cols-1 gap-3 md:grid-cols-[minmax(220px,1.35fr)_1fr_1fr_1fr_auto]"><div class="relative"><Search :size="16" class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"/><input v-model="search" type="search" placeholder="Lokasyon ara..." class="h-11 w-full rounded-lg border border-gray-200 bg-white pl-10 pr-3 text-sm"/></div><div class="relative"><select v-model="companyFilter" class="h-11 w-full appearance-none rounded-lg border px-3 pr-9 text-sm"><option value="all">Tüm Şirketler</option><option v-for="x in companyOptions" :key="x" :value="x">{{x}}</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div><div class="relative"><select v-model="cityFilter" class="h-11 w-full appearance-none rounded-lg border px-3 pr-9 text-sm"><option value="all">Tüm İller</option><option v-for="x in cityOptions" :key="x" :value="x">{{x}}</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div><div class="relative"><select v-model="statusFilter" class="h-11 w-full appearance-none rounded-lg border px-3 pr-9 text-sm"><option value="all">Tüm Durumlar</option><option value="active">Aktif</option><option value="passive">Pasif</option></select><ChevronDown :size="15" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"/></div><button type="button" class="inline-flex h-11 items-center justify-center gap-2 rounded-lg border px-4 text-sm" @click="resetFilters"><Filter :size="15"/> Filtreleri Temizle</button></div></section><div v-if="loading" class="rounded-xl border bg-white p-12 text-center text-sm text-gray-500">Lokasyonlar yükleniyor...</div><LocationDataTable v-else :locations="paginatedLocations" :filtered-count="filteredLocations.length" :current-page="currentPage" :total-pages="totalPages" :visible-pages="visiblePages" :per-page="perPage" @view="goToLocation" @edit="edit" @delete="askDelete" @update:current-page="currentPage=$event" @update:per-page="perPage=$event"/><LocationCreateDrawer v-model="createDrawerOpen" @saved="upsertLocation"/><LocationEditDrawer v-model="editDrawerOpen" :location="editingLocation" :loading="editLoading" @save="update"/><ConfirmationModal v-model:open="deleteDialogOpen" title="Lokasyonu Sil" message="Bu lokasyonu silmek istediğinize emin misiniz? Bu işlem geri alınamaz." confirm-text="Sil" cancel-text="Vazgeç" :loading="deleting" @confirm="confirmDelete"/></div></div></template>
